-- profiles.updated_at: server-side, not client-supplied.
-- CREATE FUNCTION, not OR REPLACE: a name collision must fail this
-- migration loudly rather than silently overwrite an existing function.
CREATE FUNCTION public.lockdin_set_profiles_updated_at()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION public.lockdin_set_profiles_updated_at() FROM PUBLIC;
--> statement-breakpoint
REVOKE ALL ON FUNCTION public.lockdin_set_profiles_updated_at() FROM anon;
--> statement-breakpoint
REVOKE ALL ON FUNCTION public.lockdin_set_profiles_updated_at() FROM authenticated;
--> statement-breakpoint
CREATE TRIGGER lockdin_profiles_set_updated_at
  BEFORE UPDATE ON public.profiles
  FOR EACH ROW
  EXECUTE FUNCTION public.lockdin_set_profiles_updated_at();
--> statement-breakpoint

-- Bootstrap profile on Auth signup (no username, no onboarded_at, no
-- tasks). Blank-string metadata is treated as absent, not stored as empty
-- text, so a client sending full_name: "" does not defeat the NULL default.
CREATE FUNCTION public.lockdin_handle_new_user()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  INSERT INTO public.profiles (id, full_name)
  VALUES (
    NEW.id,
    COALESCE(
      NULLIF(BTRIM(NEW.raw_user_meta_data->>'full_name'), ''),
      NULLIF(BTRIM(NEW.raw_user_meta_data->>'name'), '')
    )
  );
  RETURN NEW;
END;
$$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION public.lockdin_handle_new_user() FROM PUBLIC;
--> statement-breakpoint
REVOKE ALL ON FUNCTION public.lockdin_handle_new_user() FROM anon;
--> statement-breakpoint
REVOKE ALL ON FUNCTION public.lockdin_handle_new_user() FROM authenticated;
--> statement-breakpoint
CREATE TRIGGER lockdin_on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW
  EXECUTE FUNCTION public.lockdin_handle_new_user();
--> statement-breakpoint

-- Idempotent backfill for Auth users that predate the trigger (report only
-- counts from this, per docs/sql/phase2/phase2-post-migration-verification.sql).
-- Same blank-string normalisation as the trigger above.
INSERT INTO public.profiles (id, full_name)
SELECT
  u.id,
  COALESCE(
    NULLIF(BTRIM(u.raw_user_meta_data->>'full_name'), ''),
    NULLIF(BTRIM(u.raw_user_meta_data->>'name'), '')
  )
FROM auth.users AS u
ON CONFLICT (id) DO NOTHING;
--> statement-breakpoint

