-- No INSERT/DELETE policies for authenticated/anon: trigger/cascade only.

-- Explicit privilege baseline: revoke everything first (PUBLIC, then the
-- specific roles), then grant back only the exact intended access. Do not
-- rely on default/table-level grants left over from table creation.
-- Revoking from PUBLIC matters independently of revoking from anon/
-- authenticated: any role (including future roles) inherits whatever is
-- granted to PUBLIC, so a PUBLIC grant would silently defeat every
-- anon/authenticated REVOKE below it.
REVOKE ALL PRIVILEGES ON TABLE public.profiles FROM PUBLIC;
--> statement-breakpoint
REVOKE ALL PRIVILEGES ON TABLE public.profiles FROM anon, authenticated;
--> statement-breakpoint
GRANT SELECT ON TABLE public.profiles TO authenticated;
--> statement-breakpoint
-- Column-level UPDATE: safe profile fields only. id, username,
-- onboarded_at, created_at, and updated_at are intentionally NOT granted to
-- authenticated — username/onboarded_at are reserved for a later reviewed
-- onboarding operation (not implemented in Slice 1); id and the timestamps
-- are never client-writable. anon gets no access to profiles at all.
GRANT UPDATE (full_name, level, exam_session) ON TABLE public.profiles TO authenticated;
--> statement-breakpoint

